// Replace this array with your projects. All current entries are sample content.
const projects = [
  {id:'between-objects', title:'Between Objects', ko:'사물과 사물 사이', type:'Product', year:'2026', ratio:'.82', bg:'#eeeee9', description:'사물 사이의 관계와 쓰임을 탐구하는 제품 디자인 예시 프로젝트입니다. 실제 작업의 배경, 관찰, 디자인 과정과 결과를 이곳에 기록할 수 있습니다.'},
  {id:'common-ground', title:'Common Ground', ko:'함께 머무는 풍경', type:'Space', year:'2026', ratio:'1.6', bg:'#f7f7f3', description:'일상 속에서 함께 머무는 공간을 주제로 한 예시 프로젝트입니다. 공간의 맥락과 사용자 경험, 설계 의도를 실제 프로젝트 내용으로 교체할 수 있습니다.'},
  {id:'a-new-routine', title:'A New Routine', ko:'새로운 일상의 방식', type:'Brand identity', year:'2026', ratio:'1.25', bg:'#e8e8e3', description:'일상적인 습관에서 새로운 가능성을 발견하는 브랜드 디자인 예시입니다. 브랜드의 핵심 개념과 시각 언어가 전개되는 과정을 담는 영역입니다.'},
  {id:'soft-structure', title:'Soft Structure', ko:'유연한 구조', type:'Product', year:'2025', ratio:'.88', bg:'#efefeb', description:'구조와 감각의 균형을 살펴보는 제품 디자인 예시입니다. 소재 연구, 형태 실험, 프로토타입과 최종 결과를 순서대로 소개할 수 있습니다.'},
  {id:'traces-of-place', title:'Traces of Place', ko:'장소의 흔적', type:'Editorial', year:'2025', ratio:'1.4', bg:'#f5f5f0', description:'장소에 남아 있는 기록을 엮는 편집 디자인 예시입니다. 리서치 자료와 편집 방향, 지면 구성의 원리를 실제 작업 내용으로 채울 수 있습니다.'},
  {id:'in-between', title:'In—Between', ko:'경계에서 발견한 것들', type:'Space', year:'2025', ratio:'1.25', bg:'#e9e9e4', description:'공간과 공간의 경계를 다루는 디자인 예시입니다. 현장에서 발견한 질문이 공간적 제안으로 이어지는 과정을 소개하는 영역입니다.'},
  {id:'small-gestures', title:'Small Gestures', ko:'작은 움직임', type:'Brand identity', year:'2024', ratio:'1.2', bg:'#f5f5f1', description:'작은 몸짓에서 출발한 시각 아이덴티티 예시입니다. 로고, 타이포그래피와 다양한 매체의 응용을 하나의 시각 언어로 소개할 수 있습니다.'},
  {id:'collected-notes', title:'Collected Notes', ko:'모아둔 생각들', type:'Editorial', year:'2024', ratio:'.9', bg:'#edede8', description:'관찰과 생각을 모은 편집 디자인 예시입니다. 이미지, 텍스트, 실험을 연결하는 작업의 구성과 결과를 담을 수 있습니다.'}
];
const types=['All','Product','Space','Brand identity','Editorial'];
const main=document.querySelector('main');
const cursor=document.querySelector('.cursor-label');
const state={filter:'All',view:'home'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function placeholder(p,asset='01',ratio=p.ratio){return `<div class="placeholder" role="img" aria-label="${esc(p.title)} — image placeholder ${asset}" style="--ratio:${ratio};--bg:${p.bg}"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><line x1="0" y1="0" x2="100" y2="100"/><line x1="100" y1="0" x2="0" y2="100"/></svg><span class="asset-label" aria-hidden="true"><span>IMAGE ${asset}</span><span>HANGANG TUH</span></span></div>`}
function card(p){return `<a class="project-card" href="#/project/${p.id}" data-project="${p.id}"><div class="card-meta"><div><h2>${p.title}</h2><p class="type">${p.type}</p></div><div class="right-meta"><p>${p.ko}</p><p class="year">${p.year} · Sample</p></div></div>${placeholder(p)}<span class="card-arrow" aria-hidden="true">↗</span></a>`}
function filterButtons(){return `<div class="filters" aria-label="Filter by discipline">${types.map(t=>`<button type="button" data-filter="${t}" class="${state.filter===t?'active':''}" aria-pressed="${state.filter===t}">${t}</button>`).join('')}</div>`}
function selected(){return projects.filter(p=>state.filter==='All'||p.type===state.filter)}
function home(){const left=projects.filter((_,i)=>i%2===0),right=projects.filter((_,i)=>i%2===1);return `<div class="home-meta"><span>Selected works, 2024—2026</span><span class="intro">A collection of ideas, forms <span>and possibilities.</span></span><span>01—08</span></div><div class="home-grid">${[left,right].map((list,i)=>`<div class="project-column">${list.map(card).join('')}<div class="column-note"><span>${i?'Continue the conversation':'An ongoing collection'}</span><a href="#/${i?'info':'index'}">${i?'Info ↗':'View index ↗'}</a></div></div>`).join('')}</div>`}
function grid(){const list=selected();return `<div class="subbar"><span class="eyebrow">Projects / 2024—2026</span>${filterButtons()}<span class="results-count">${String(list.length).padStart(2,'0')} projects</span></div><div class="project-grid">${list.map(card).join('')}</div>`}
function index(){const list=selected();return `<div class="index-layout"><aside class="index-sidebar"><p>Index<br><span class="eyebrow">2024—2026</span></p><p class="eyebrow">Type of work</p>${filterButtons()}<p class="index-caption">An overview of selected works.<br>프로젝트명에 마우스를 올려<br>이미지를 미리 볼 수 있습니다.</p></aside><section aria-label="Project index"><div class="index-table-head"><span>No.</span><span>Project</span><span>Discipline</span><span>Year</span></div>${list.map(p=>`<a class="index-row" href="#/project/${p.id}" data-preview="${p.id}"><span>${String(projects.indexOf(p)+1).padStart(2,'0')}</span><span class="row-title">${p.title}</span><span class="row-type">${p.type}</span><span class="row-year">${p.year} ↗</span></a>`).join('')}<div class="index-bottom"><span>${String(list.length).padStart(2,'0')} selected projects</span><span>Sample project archive</span></div></section></div><div class="index-preview" aria-hidden="true"></div>`}
function info(){const p={title:'Portrait',ratio:'1.5',bg:'#f0f0eb'};return `<div class="info-layout"><div class="info-caption">Info / About</div><article class="info-body"><h1>HANGANG TUH<br>Selected perspectives.</h1><p class="korean">익숙한 일상에서 질문을 발견하고,<br>사물과 공간, 이미지로 생각을 연결합니다.</p><p class="english">Finding questions in the everyday.<br>Connecting ideas through objects, spaces, and images.</p>${placeholder(p,'PROFILE')}<p class="draft-note">소개 문구 초안입니다. 자신의 디자인 관점과 관심 분야를 이곳에 적어주세요.<br>이 사이트의 프로젝트명과 설명은 구성을 보여주기 위한 예시 콘텐츠입니다.</p></article><aside class="info-aside"><section><h2>Name</h2><p>HANGANG TUH</p></section><section><h2>Disciplines</h2><p>Product<br>Space<br>Brand identity<br>Editorial</p></section><section><h2>Contact</h2><p>연락처는 추후 업데이트됩니다.</p></section><section><h2>Archive</h2><p>2024—2026<br>Selected works & experiments</p></section><section><h2>Elsewhere</h2><p class="draft-note">소셜 링크를 추가할 수 있습니다.</p></section></aside></div>`}
function detail(p){const n=projects[(projects.indexOf(p)+1)%projects.length];return `<div class="detail-layout"><aside class="detail-info"><span class="detail-number">Project ${String(projects.indexOf(p)+1).padStart(2,'0')} / 08</span><h1>${p.title}</h1><dl><dt>Project</dt><dd>${p.ko}</dd><dt>Discipline</dt><dd>${p.type}</dd><dt>Year</dt><dd>${p.year}</dd><dt>Status</dt><dd>Sample project / 예시 콘텐츠</dd></dl><p class="description">${p.description}</p><a href="#/projects" class="back-link">← All projects</a></aside><article class="detail-assets" aria-label="${p.title} gallery">${placeholder(p,'01','1.3')}${placeholder(p,'02','.9')}<div class="asset-pair">${placeholder(p,'03')}${placeholder(p,'04')}</div>${placeholder(p,'05','1.6')}<a class="next-project" href="#/project/${n.id}"><span>Next project</span><span>${n.title} ↗</span></a></article></div>`}
function render({keepScroll=false}={}){const path=location.hash.replace(/^#\/?/,'').split('/');state.view=path[0]||'home';cursor.classList.remove('visible');document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(state.view==='project'?'projects':state.view);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});let html,title;if(state.view==='project'){const p=projects.find(p=>p.id===path[1]);html=p?detail(p):`<p>Project not found.</p><a class="back-link" href="#/projects">← All projects</a>`;title=p?.title||'Project not found'}else{html=state.view==='projects'?grid():state.view==='index'?index():state.view==='info'?info():home();title=state.view==='home'?'Portfolio':state.view[0].toUpperCase()+state.view.slice(1)}main.innerHTML=`<div class="${keepScroll?'':'page-enter'}">${html}</div>`;document.title=`${title} — HANGANG TUH`;document.querySelector('#announcement').textContent=keepScroll?`${selected().length} projects shown`:title;if(!keepScroll)window.scrollTo({top:0,behavior:'instant'});bind()}
function bind(){main.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;render({keepScroll:true});main.querySelector(`[data-filter="${state.filter}"]`)?.focus({preventScroll:true})}));main.querySelectorAll('[data-project]').forEach(a=>{a.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')cursor.classList.add('visible')});a.addEventListener('pointerleave',()=>cursor.classList.remove('visible'))});const preview=main.querySelector('.index-preview');main.querySelectorAll('[data-preview]').forEach(a=>{const show=()=>{const p=projects.find(p=>p.id===a.dataset.preview);preview.innerHTML=placeholder(p);preview.classList.add('show')};a.addEventListener('pointerenter',show);a.addEventListener('focus',show);a.addEventListener('pointerleave',()=>preview.classList.remove('show'));a.addEventListener('blur',()=>preview.classList.remove('show'))})}
document.addEventListener('pointermove',e=>{cursor.style.left=`${Math.min(e.clientX,innerWidth-135)}px`;cursor.style.top=`${Math.min(e.clientY,innerHeight-60)}px`},{passive:true});
document.querySelector('#top').addEventListener('click',()=>window.scrollTo({top:0,behavior:reduced?'instant':'smooth'}));
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('hashchange',()=>{state.filter='All';render();main.focus({preventScroll:true})});
render();
